function validate([mountainHeight, workerTimes]) {
  if (mountainHeight < 1 || mountainHeight > 100000) return 'mountainHeight is between 1 and 10^5.';
  if (workerTimes.length < 1 || workerTimes.length > 10000) return 'workerTimes needs 1 to 10^4 workers.';
  if (workerTimes.some(t => t < 1 || t > 1000000)) return 'Each work time is between 1 and 10^6.';
