function minNumberOfSeconds(mountainHeight, workerTimes) {
  // The most units a worker with time t removes within seconds: the largest x with t * x(x+1)/2 <= seconds.
  const unitsWithin = (t, seconds) => {
    let x = Math.floor((Math.sqrt(1 + (8 * seconds) / t) - 1) / 2);
    x = Math.min(x, mountainHeight);
    // The square root is a floating-point estimate, so correct it with exact integer checks.
    while (x > 0 && t * ((x * (x + 1)) / 2) > seconds) {
      x--;
    }
    while (x < mountainHeight && t * (((x + 1) * (x + 2)) / 2) <= seconds) {
      x++;
    }
    return x;
  };
  const canFinish = (seconds) => {
    let removed = 0;
    for (const t of workerTimes) {
      removed += unitsWithin(t, seconds);
      if (removed >= mountainHeight) {
        return true;
      }
    }
    return false;
  };
  let low = 1;
  let high = Math.min(...workerTimes) * ((mountainHeight * (mountainHeight + 1)) / 2);
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (canFinish(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

