function minNumberOfSeconds(mountainHeight, workerTimes) {
  // best[h]: least time for the workers so far to remove h units, trying every share x for each new worker.
  let best = Array.from({ length: mountainHeight + 1 }, (_, h) => (h === 0 ? 0 : Infinity));
  for (const t of workerTimes) {
    const next = best.slice();
    for (let h = 1; h <= mountainHeight; h++) {
      for (let x = 1; x <= h; x++) {
        next[h] = Math.min(next[h], Math.max(best[h - x], (t * x * (x + 1)) / 2));
      }
    }
    best = next;
  }
  return best[mountainHeight];
}

