function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  if (size === 'large') {
    const shape = pick(3);
    // The largest possible answer: one slowest worker removes the tallest mountain alone.
    if (shape === 0) return [100000, [1000000]];
    // Many identical fast workers share the work evenly.
    if (shape === 1) return [100000, new Array(2000).fill(1)];
    return [99000 + pick(1001), Array.from({ length: 2000 }, () => 1 + pick(1000000))];
  }
  const span = [3, 10, 1000000][pick(3)];
  const workerTimes = Array.from({ length: 1 + pick(6) }, () => 1 + pick(span));
  return [1 + pick(30), workerTimes];
}
